out=Path('translation/scenes');out.mkdir(exist_ok=True)
for p in Path('work/scene_audio/asr').glob('*.json'):
 d=json.loads(p.read_text(encoding='utf-8'));h=p.stem
 if h not in translations:
  if d['segments']:continue
  translations[h]=[]
 assert len(translations[h])==len(d['segments']),(h,len(translations[h]),len(d['segments']))
 for r,k in zip(d['segments'],translations[h]):r['ko']=k
 d['status']='draft_asr_review_required'
 (out/p.name).write_text(json.dumps(d,ensure_ascii=False,indent=2),encoding='utf-8')
print('scene drafts',len(list(out.glob('*.json'))))
